 const keys=[
  STORAGE,SETTINGS,SESSION,USER_PROFILE,
  SCHOOL_PREFS_KEY,SCHOOL_COMPARE_KEY,SCHOOL_PARTNER_KEY,SCHOOL_DASHBOARD_KEY,
  PASSPORT_KEY,ROADMAP_KEY,ONBOARDING_KEY,PRIVACY_PREFS_KEY
 ];
