       knownWords:Array.isArray(p.knownWords)?p.knownWords:[],
       knownPhrases:Array.isArray(p.knownPhrases)?p.knownPhrases:[],
       review:p.review&&typeof p.review==='object'?allowedQuestionMap(p.review):{},
